UPDATE [Станции(архив)] SET [Станции(архив)].gaz = IIf([Станции(архив)].gaz Is Null,0,[Станции(архив)].gaz), [Станции(архив)].mazut = IIf([Станции(архив)].mazut Is Null,0,[Станции(архив)].mazut), [Станции(архив)].torf = IIf([Станции(архив)].torf Is Null,0,[Станции(архив)].torf), [Станции(архив)].ugol = IIf([Станции(архив)].ugol Is Null,0,[Станции(архив)].ugol), [Станции(архив)].E = IIf([Станции(архив)].E Is Null,0,[Станции(архив)].E), [Станции(архив)].Q = IIf([Станции(архив)].Q Is Null,0,[Станции(архив)].Q)
WHERE ((([Станции(архив)].Q) Is Null) OR (([Станции(архив)].E) Is Null) OR (([Станции(архив)].gaz) Is Null) OR (([Станции(архив)].mazut) Is Null) OR (([Станции(архив)].torf) Is Null) OR (([Станции(архив)].ugol) Is Null));
